    sc.textContent = score + ' pts';
    const msg = document.createElement('p');
    msg.className = 'Game_WhackAMole__overlayMsg';
    msg.textContent = hits + ' valid hit' + (hits === 1 ? '' : 's') + ' \u00b7 ' + misses + ' distractor hit' + (misses === 1 ? '' : 's');
    const btn = document.createElement('button');
    btn.type = 'button';
    btn.className = 'Game_WhackAMole__btn';
    btn.textContent = 'Play again';
    btn.addEventListener('click', startRound);
    ov.appendChild(t); ov.appendChild(sc); ov.appendChild(msg); ov.appendChild(btn);
